CREATE OR REPLACE PROCEDURE p() RETURNS VARCHAR LANGUAGE SQL AS $$
DECLARE
  n NUMBER(10,2);
BEGIN
  EXECUTE IMMEDIATE 'DECLARE d INTEGER; BEGIN d := 1; END;';
  n := 3.14159;
  RETURN :n::VARCHAR;
END
$$

CREATE OR REPLACE PROCEDURE p() RETURNS VARCHAR LANGUAGE SQL AS $$
DECLARE
  c CURSOR FOR SELECT id FROM nums;
  v INTEGER;
BEGIN
  OPEN c;
  EXECUTE IMMEDIATE 'DECLARE d INTEGER; BEGIN d := 1; END;';
  FETCH c INTO v;
  CLOSE c;
  RETURN :v::VARCHAR;
END
$$

